"""B55: planning names generated by the old planning form ("Rotation tous les
1 · mercredi 19:37", "Weekly rotation · Sunday 09:00") become the natural
sentence the form now writes ("Rotation chaque mercredi à 19:37"), once, at
startup. Names typed by the operator never match the old patterns and are
left alone. Same wording as `autoTitle` in apps/web/src/views/planning/planningForm.ts.
"""

from __future__ import annotations

import logging
import re
from datetime import UTC, datetime
from zoneinfo import ZoneInfo

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.models import AppSetting, ScheduledBackupEvent

logger = logging.getLogger(__name__)

MARKER_KEY = "meta.planning_titles_natural"
_LEGACY = {
    "fr": re.compile(r"^(Rotation hebdo|Rotation toutes les 2 semaines|Rotation mensuelle|Rotation quotidienne|Rotation tous les \d+) · .+$"),
    "en": re.compile(r"^(Weekly rotation|Rotation every 2 weeks|Monthly rotation|Daily rotation|Rotation every \d+) · .+$"),
}
WEEKDAYS = {
    "fr": ("lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche"),
    "en": ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"),
}
SENTENCES = {
    "fr": {
        "daily": "chaque jour à {time}", "dailyN": "tous les {n} jours à {time}",
        "weekly": "chaque {weekday} à {time}", "weeklyN": "un {weekday} sur {n} à {time}",
        "monthly": "le {day} de chaque mois à {time}", "monthlyN": "le {day}, tous les {n} mois, à {time}",
        "and": " et ",
    },
    "en": {
        "daily": "every day at {time}", "dailyN": "every {n} days at {time}",
        "weekly": "every {weekday} at {time}", "weeklyN": "every {n} weeks on {weekday} at {time}",
        "monthly": "on day {day} of every month at {time}", "monthlyN": "on day {day}, every {n} months, at {time}",
        "and": " and ",
    },
}


def legacy_language(title: str) -> str | None:
    for language, pattern in _LEGACY.items():
        if pattern.match(title or ""):
            return language
    return None


def natural_title(event: ScheduledBackupEvent, language: str) -> str:
    texts = SENTENCES[language]
    start = event.window_starts_at if event.window_starts_at.tzinfo else event.window_starts_at.replace(tzinfo=UTC)
    try:
        local = start.astimezone(ZoneInfo(event.timezone or "UTC"))
    except Exception:  # noqa: BLE001 — a bad zone keeps UTC
        local = start
    config = event.recurrence_config or {}
    interval = int(config.get("interval") or 1)
    kind = getattr(event.recurrence_type, "value", event.recurrence_type)
    days = sorted(int(day) for day in config.get("weekdays") or [local.weekday()])
    names = [WEEKDAYS[language][day % 7] for day in days]
    weekday = names[0] if len(names) == 1 else ", ".join(names[:-1]) + texts["and"] + names[-1]
    unit = "daily" if kind == "daily" else "monthly" if kind == "monthly" else "weekly"
    template = texts[f"{unit}N" if interval > 1 else unit]
    when = template.format(time=local.strftime("%H:%M"), weekday=weekday, n=interval, day=local.day)
    return f"Rotation {when}"


def rename_legacy_titles(db: Session, now: datetime | None = None) -> int:
    """Once (marker row). Returns the plannings renamed."""
    if db.get(AppSetting, MARKER_KEY) is not None:
        return 0
    renamed = 0
    for event in db.scalars(select(ScheduledBackupEvent)):
        language = legacy_language(event.title)
        if language and getattr(event.recurrence_type, "value", event.recurrence_type) != "once":
            event.title = natural_title(event, language)[:255]
            renamed += 1
    db.add(AppSetting(key=MARKER_KEY, value=(now or datetime.now(UTC)).isoformat()))
    db.commit()
    if renamed:
        logger.info("%s planning name(s) rewritten as a sentence", renamed)
    return renamed
